<?php
declare(strict_types=1);
require __DIR__.'/../app/ExperienceOperatorAddon.php';
function expect(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
function denied(callable $fn):bool{try{$fn();return false;}catch(RuntimeException){return true;}}
$p=new PDO('sqlite::memory:');$p->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
$p->exec('CREATE TABLE destinations(id INTEGER PRIMARY KEY,slug TEXT,publication_status TEXT);CREATE TABLE points_of_interest(id INTEGER PRIMARY KEY,destination_id INTEGER,slug TEXT,poi_type TEXT,publication_status TEXT,display_order INTEGER);CREATE TABLE point_of_interest_translations(point_of_interest_id INTEGER,locale TEXT,name TEXT);CREATE TABLE businesses(id INTEGER PRIMARY KEY,public_id TEXT,slug TEXT,destination_id INTEGER,publication_status TEXT,operation_status TEXT,category_code TEXT);CREATE TABLE service_categories(code TEXT,is_active INTEGER);CREATE TABLE business_categories(business_id INTEGER,category_code TEXT);CREATE TABLE business_translations(business_id INTEGER,locale TEXT,display_name TEXT,summary TEXT);CREATE TABLE business_subscriptions(id INTEGER PRIMARY KEY,business_id INTEGER,plan_code TEXT,status TEXT,reviewed_at TEXT,starts_at TEXT,ends_at TEXT)');
$p->exec(file_get_contents(__DIR__.'/../database/migrations/041-experience-operator-addon.sqlite.sql'));
$p->exec("INSERT INTO destinations VALUES(1,'jerico','published'),(2,'otro','published');INSERT INTO points_of_interest VALUES(1,1,'parapente','experience','published',1),(2,1,'oculta','experience','draft',2),(3,2,'otra','experience','published',1);INSERT INTO point_of_interest_translations VALUES(1,'es','Parapente'),(2,'es','Oculta'),(3,'es','Otra');INSERT INTO businesses VALUES(1,'prueba-id','prueba',1,'published','ABIERTO','experiencias');INSERT INTO service_categories VALUES('experiencias',1);INSERT INTO business_translations VALUES(1,'es','Operador Ficticio','Prueba');INSERT INTO business_subscriptions VALUES(1,1,'featured','pending',NULL,NULL,NULL)");
$s=new ExperienceOperatorAddon($p);expect($s->eligibleBusiness(1),'Primary operator eligible');$p->exec("UPDATE businesses SET category_code='hospedaje'");expect(!$s->eligibleBusiness(1),'Hotel alone ineligible');expect(denied(fn()=>$s->requireEligible(1)),'Reject nonoperator');$p->exec("INSERT INTO business_categories VALUES(1,'experiencias')");expect($s->eligibleBusiness(1),'Secondary operator eligible');
foreach(['monthly'=>29900,'quarterly'=>74750,'semiannual'=>155480,'annual'=>299000] as $period=>$price){$q=$s->quote('featured',$period,1,1);expect((float)$q['amount']===$price*1.0,'Incorrect addon price');}
expect(49900+(float)$s->quote('featured','monthly',1,1)['amount']===79800.0,'Featured + addon = 79800');
expect(denied(fn()=>$s->quote('free','monthly',1,1)),'Free cannot buy addon');expect(denied(fn()=>$s->quote('featured','monthly',1,2)),'Draft excluded');expect(denied(fn()=>$s->quote('featured','monthly',1,3)),'Foreign place excluded');
$s->attach(1,$s->quote('featured','monthly',1,1));expect(!$s->active(1),'Pending payment must not advertise');
$p->exec("UPDATE business_subscriptions SET status='active',reviewed_at=CURRENT_TIMESTAMP,starts_at=datetime('now','-1 day'),ends_at=datetime('now','+29 days')");expect(count($s->active(1))===1,'Active paid placement missing');
foreach(["DELETE FROM business_categories","UPDATE service_categories SET is_active=0","UPDATE business_subscriptions SET ends_at=datetime('now','-1 day')","UPDATE points_of_interest SET publication_status='draft' WHERE id=1","UPDATE businesses SET destination_id=2","UPDATE business_subscriptions SET plan_code='free'"] as $change){$p->beginTransaction();$p->exec($change);expect(!$s->active(1),'Invalid placement must disappear');$p->rollBack();}
echo "OK: four prices, 79800 total, paid prerequisite, same place/published experience, pending/active/expiry/moved/Free visibility.\n";
